import java.util.Scanner;

public class BubbleSort {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Prompt the user to enter the size of the array
        System.out.print("Enter the size of the array: ");

        // Read the input and validate it to ensure it is a positive integer
        int size = 0;
        try {
            size = Integer.parseInt(scanner.nextLine());

            if (size <= 0) {
                throw new IllegalArgumentException("Size must be a positive integer.");
            }
        } catch (NumberFormatException e) {
            System.out.println("Invalid input. Size must be a positive integer.");
            System.exit(0);
        }

        // Prompt the user to enter the elements of the array
        System.out.println("Enter the elements of the array, one by one:");
        int[] array = new int[size];

        for (int i = 0; i < size; i++) {
            System.out.print("Element " + (i + 1) + ": ");

            // Read the input and validate it to ensure it is an integer
            try {
                array[i] = Integer.parseInt(scanner.nextLine());
            } catch (NumberFormatException e) {
                System.out.println("Invalid input. Elements must be integers.");
                System.exit(0);
            }
        }

        // Implement the bubble sort algorithm to sort the array in ascending order
        for (int i = 0; i < size - 1; i++) {
            for (int j = 0; j < size - i - 1; j++) {
                if (array[j] > array[j + 1]) {
                    // Swap adjacent elements if they are in the wrong order
                    int temp = array[j];
                    array[j] = array[j + 1];
                    array[j + 1] = temp;
                }
            }
        }

        // Display the sorted array to the user
        System.out.println("Sorted array:");
        for (int i = 0; i < size; i++) {
            System.out.print(array[i] + " ");
        }
    }
}

